"""Six-metric test report; frozen RGB-selected configs, no target retuning."""
import argparse,csv,hashlib,json,math,statistics,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from scripts.search_quality_speed import save
BASE=Path('/mnt/rfs/users/xiangliangyu/projects/Sparse-Attention-VGGT/outputs/history_A_special5_cluster12_speed_20261106')
FIELDS=('auc03','auc30','acc','comp','cd','f1')
def read(p):return json.loads(p.read_text())
def csvwrite(p,rows):
 with p.open('w',newline='') as f:
  writer=csv.DictWriter(f,fieldnames=list(rows[0]));writer.writeheader();writer.writerows(rows)
def table(headers,rows):return '\n'.join(['| '+' | '.join(headers)+' |','| '+' | '.join(['---']*len(headers))+' |']+['| '+' | '.join(map(str,r))+' |' for r in rows])
def fmt(k,v):return f"{v*(100 if k in ('auc03','auc30','f1') else 1):.5f}"
def main():
 p=argparse.ArgumentParser();p.add_argument('--output',type=Path,required=True);a=p.parse_args();root=a.output;out=root/'final_quality';plan=read(out/'plan.json');done=read(out/'completion.json');selection=read(root/'final_selection.json');assert done['complete'];old_summary=read(BASE/'summary.json')
 for path,sha in plan['source_sha256'].items():assert hashlib.sha256((ROOT/path).read_bytes()).hexdigest()==sha,path
 rows=[];layers=[];audits=[];macros=[];oldmac=[];acceptance={}
 for c in selection['candidates']:
  name=c['name'];assert hashlib.sha256((ROOT/c['config']).read_bytes()).hexdigest()==c['config_sha256'];cfg=read(ROOT/c['config'])
  for ds,scenes in plan['datasets'].items():
   for scene in scenes:
    parent=out/'runs'/name/ds/scene;r=read(parent/'result.json');ref=read(BASE/'runs'/ds/scene/'history_A_special5_cluster12_fast/result.json');assert r['quality']['complete'] and ref['quality']['complete'];assert r['input']==ref['input'] and r['quality_protocol']==ref['quality_protocol'];assert r['input']['checkpoint_sha256']=='b08a43baa2db1aad9718e71e098831b8ad32f6f6826c802e9eb714aa34420969'
    for key,value in cfg.items():assert r['config'][key]==value,key
    monitor=read(out/'monitors'/f'{name}_{ds}_{scene}.json');assert monitor['returncode']==0 and not monitor['same_gpu_overlap_detected'] and monitor['max_simultaneous_gpu_applications']==1
    t=r['timing'];assert t['warmup']==1 and t['repeats']==3 and len(t['samples'])==3;assert t['median_seconds']==statistics.median(x['seconds'] for x in t['samples']);assert abs(r['quality']['values']['cd']-(r['quality']['values']['acc']+r['quality']['values']['comp'])/2)<1e-9
    q=r['quality']['values'];rq=ref['quality']['values'];change={k:100*(q[k]/rq[k]-1) for k in FIELDS}
    rows.append(dict(method=name,dataset=ds,scene=scene,frames=r['frames'],**q,seconds=t['median_seconds'],reference_batch_seconds=ref['timing']['median_seconds'],reference_batch_time_ratio=t['median_seconds']/ref['timing']['median_seconds'],warm_peak_allocated_gib=max(x['peak_allocated_gib'] for x in t['samples']),warm_peak_reserved_gib=max(x['peak_reserved_gib'] for x in t['samples']),cold_seconds=t['cold_samples'][0]['seconds'],including_cold_peak_allocated_gib=max(x['peak_allocated_gib'] for x in t['samples']+t['cold_samples']),speedup_vs_dense=None,speedup_reason='No paired Dense timing; unchanged control not rerun',**{k+'_change_percent':change[k] for k in FIELDS}))
    lr=read(parent/'layers.json');assert len(lr)==24
    shape=r['input']['shape'];patches=r['frames']*(shape[-2]//14)*(shape[-1]//14)
    for layer in lr:
     assert layer['fine_clusters']==math.floor(cfg['cluster_fraction']*patches);assert layer['actual_unique_density']<=.25+1e-6;assert layer['dense_special_query_count']==r['frames']*5
     layers.append(dict(method=name,dataset=ds,scene=scene,layer=layer['layer'],fine_clusters=layer['fine_clusters'],patch_budget=layer['patch_budget'],special_keys=layer['special_keys'],actual_density=layer['actual_unique_density'],counts_mean=layer['counts_mean'],unused_budget_mean=layer['unused_budget_mean'],**{f'state_{i}_clusters_mean':layer.get(f'state_{i}_clusters_mean') for i in [0,1,5,10]}))
    audits.append(dict(method=name,dataset=ds,scene=scene,complete=True,input_protocol_checkpoint_equal=True,isolated=True,gpu_uuid=monitor['gpu_uuid']))
   rr=[r for r in rows if r['method']==name and r['dataset']==ds];assert len(rr)==len(scenes)
   macro=dict(method=name,dataset=ds,scenes=len(rr),**{k:statistics.mean(r[k] for r in rr) for k in FIELDS},seconds=statistics.mean(r['seconds'] for r in rr),reference_batch_seconds=statistics.mean(r['reference_batch_seconds'] for r in rr),warm_peak_allocated_gib=max(r['warm_peak_allocated_gib'] for r in rr),warm_peak_reserved_gib=max(r['warm_peak_reserved_gib'] for r in rr),mean_cold_seconds=statistics.mean(r['cold_seconds'] for r in rr),including_cold_peak_allocated_gib=max(r['including_cold_peak_allocated_gib'] for r in rr),speedup_vs_dense=None)
   macro['reference_batch_time_ratio']=macro['seconds']/macro['reference_batch_seconds'];old=next(r for r in old_summary['macro'] if r['dataset']==ds);changes={k:100*(macro[k]/old[k]-1) for k in FIELDS};macro.update({k+'_change_percent':v for k,v in changes.items()});macros.append(macro)
   acceptance[name+'_'+ds]=dict(quality_relative_changes_percent=changes,no_metric_worse_than_current=all((macro[k]>=old[k] if k in ['auc03','auc30','f1'] else macro[k]<=old[k]) for k in FIELDS),pointcloud_change_within_prior2pct=all(abs(changes[k])<2 for k in ['acc','comp','cd','f1']),time_below_previous_batch=macro['seconds']<=old['seconds'],paired_target_speed_comparison=None,paired_speed_reason='Existing current-method target timings are previous-batch references; no unchanged controls rerun. Independent RGB paired validation passed.',independent_rgb_speed_pass=c['validation']['speed_pass'],independent_rgb_fidelity_pass=c['validation']['fidelity_pass'])
 for ds in plan['datasets']:
  r=next(x for x in old_summary['macro'] if x['dataset']==ds);oldmac.append(dict(dataset=ds,method='current_A12_previous_batch',scenes=r['scenes'],**{k:r[k] for k in FIELDS}))
 quality_rows=old_summary['historical_quality']+oldmac+macros
 # Keep specific historical A12 reproductions separate from current local A12.
 display=[r for r in quality_rows if r['method']!='A_all_specials_cluster12_historical']
 save(root/'summary.json',dict(complete=True,macros=macros,current_reference=oldmac,historical_controls=old_summary['historical_quality'],acceptance=acceptance,all_source_unchanged=True,selection_frozen_before_test=True,dense_speedup=None,dense_speedup_reason='No paired Dense full-forward timing; Dense and SAF3R unchanged, quality and timings not rerun',sampling=dict(sevenscenes='7 scenes x128frames',eth3d='11 scenes,14–76frames,377frames total')))
 save(root/'audit.json',dict(passed=True,quality_runs=len(rows),source_unchanged=True,rows=audits));csvwrite(root/'per_scene.csv',rows);csvwrite(root/'macro.csv',macros);csvwrite(root/'per_layer.csv',layers)
 lines=['# History A：独立超参数搜索与降低保留率后的完整评测','', '先完成独立RGB搜索与验证，再冻结两个候选，最后各评测一次7Scenes全七场景128帧及ETH3D既有11场景14–76帧。六项指标等场景宏平均；AUC/F1为百分数，距离米，CD=(ACC+Comp)/2，未平方。未使用7Scenes/ETH3D测试真值选参数，不按测试分数选择“最佳重复”。','', '## 实现与候选','', '保留History A、5个特殊Query全Key输出、每层当前Value更新、History概率公式、16轮预算求解及稀疏Attention。改动：12%→10%簇；head_mean→每Head4维固定正交草图（16×4=64维），减少跨Head抵消；Exact资格25%→100%，所有簇在原预算内竞争。精度优先中层21%，速度优先19%，浅/深各10%；平均保留上限15.5%/14.5%，原版16%。没有Dense层回退。','', '删除只在全Exact资格路径中未使用的Cluster-Grid overlap、残差需求/候选筛选、patch-only粗归一化及被完整覆盖的fallback计数与缓存。8帧四次真实前向，掩码、相机、深度、置信度均逐值相同。此工程变更默认关闭、显式启用；独立prior_residual补偿变种未入选，最终仍采用population补偿。','', '## 六指标宏平均','',table(['数据集','方法','场景','AUC@3 %','AUC@30 %','ACC m','Comp m','CD m','F1 %'],[[r['dataset'],r['method'],r['scenes'],*[fmt(k,r[k]) for k in FIELDS]] for r in display]),'', 'Dense/SAF3R标为historical的质量复用combined_reuse_20261031，未重跑；旧控制文件无checkpoint SHA，不能追认严格字节级匹配。当前A12参考来自history_A_special5_cluster12_speed_20261106，与本轮输入/协议/SHA逐场景核对一致。官方tracker-fixed SHA b08a43...20969，两个当前候选都保持同一文件。','', '## 完整前向、显存和冷启动','', '每场景GPU独占，1预热+3完整前向取中位数，再等场景平均。包含全部初始化/reset、聚类、历史、路由、打包、特殊Query修正及预测头；不含磁盘加载与后续CPU几何评估。表中旧A12速度是上一批历史参考，不能当作同期配对；Dense作为定义上的基线为1.00×；候选的正式Dense配对加速比N/A。独立RGB验证中每候选与A12在同卡同进程顺序配对，速度均不增加。','',table(['数据集','候选','前向 s','旧A12批次 s','时间比 新/旧','热峰值allocated GiB','平均冷前向 s','含冷启动峰值 GiB'],[[r['dataset'],r['method'],f"{r['seconds']:.6f}",f"{r['reference_batch_seconds']:.6f}",f"{r['reference_batch_time_ratio']:.4f}",f"{r['warm_peak_allocated_gib']:.3f}",f"{r['mean_cold_seconds']:.3f}",f"{r['including_cold_peak_allocated_gib']:.3f}"] for r in macros]),'', 'SAF3R已有上一批计时参考为7Scenes6.705480秒、ETH3D1.603858秒；配置为lazy first-correspondence-head Top4/frame，不是论文DINO Top-K。本轮未重跑SAF3R。不要将历史速度直接标为本轮配对加速比。','', '## 相对当前A12的变化与目标验收','', '下列为原始相对变化：AUC/F1正数为提升，ACC/Comp/CD负数为提升。之前点云变化<2%的检查单独保留；不能把局部误差代理改进当作六项几何指标全部通过。','',table(['数据集','候选',*[k+'变化 %' for k in FIELDS]],[[r['dataset'],r['method'],*[f"{r[k+'_change_percent']:+.3f}" for k in FIELDS]] for r in macros]),'', '```json',json.dumps(acceptance,indent=2,ensure_ascii=False),'```','', '## 搜索、诊断及限制','', '第一阶段60组，第二阶段26组（含对照与重复结构的因子对照），第三阶段7组（含对照）预算细化，均为有限搜索，不声称全局最优。独立校准为ScanNet scene0000_00及TUM sitting halfsphere各64RGB；验证为与最终seq01不同的chessseq03现有24RGB，以及TUM walking halfsphere128RGB。只读取RGB；全六项几何字段N/A并给出原因。精度代理为32个确定性Patch Query、当前稀疏轨迹的24层Wo投影误差，对比同QKV完整Key Attention；它不包含Dense模型完整轨迹，不保证最终几何质量。','', '候选必须在两个验证序列上同时更低误差、同卡热中位耗时不增加；预先冻结最低误差主候选与最快改进候选，不按最终测试分数换推荐身份。每个候选只做一次全数据集质量评测。54种Kernel分块参数在两个保留形状上作无真值速度/精度检查，保留原64Q/128K/4warp/2stage组合，没有把kernel微基准当端到端速度。','', 'GPU7在一次验证结束时出现NVML lost，整批排除并在GPU0重做；其余单卡独占监控保留。首次新工作目录缺少数据软链接，在图像加载前失败、六指标N/A，补齐并先核验所有冻结RGB后才正式运行。另一份ScanNet JPEG损坏在校准预检中排除并记录。所有失败原样保留。','', '关键Key分析是独立RGB上的同预算单Key反事实，不参与冻结后的选参。每组只考察8条高概率遗漏边，不能声称所有Key的全局oracle；真实Dense概率仅用于诊断。Probe0估计与Probe0真概率单独对齐，另外保留四Probe组均值，防止混淆概率定义。详见key_impact_analysis.json/key_impact_aligned。','', '## 逐场景六指标','',table(['数据集','候选','场景','帧','AUC3 %','AUC30 %','ACC m','Comp m','CD m','F1 %','前向 s'],[[r['dataset'],r['method'],r['scene'],r['frames'],*[fmt(k,r[k]) for k in FIELDS],f"{r['seconds']:.6f}"] for r in rows]),'', '原始JSON、逐层预算/状态、峰值allocated/reserved、输入帧表、源码哈希及GPU监控均归档。']
 if (root/'key_impact_analysis.json').exists():
  impact=read(root/'key_impact_analysis.json');old=impact['summary']['current'];coverage=impact['coverage']
  extra=['', '## 具体哪些Key被找回','', f"在独立校准序列预选的{old['candidate_edges']}条高概率遗漏边中，{old['positive_single_edge_swaps']}条同边数替换降低当前层Wo输出误差，其中{old['positive_approximate_cluster']}条来自仍有Rep的簇，{old['positive_never_previous_history']}条上一层不在历史集合。新主候选实际保留其中{coverage['retained_by_new']}条（{100*coverage['fraction']:.2f}%）；这不是全局Key集合的覆盖率，也不是最终几何收益。",'',f"对这些正收益候选，Probe0真实概率/同Probe估计概率的中位数为{old['median_probe0_true_over_prior']:.2f}；这是偏向重要遗漏边的条件统计，不能冒充全部边的估计误差。Head-mean Value差异能量/逐Head差异能量中位数为{old['median_head_mean_distance_over_headwise_distance']:.4f}，反映跨Head抵消。critical_keys.csv保存具体层、组、原帧与Patch坐标、真实/估计概率、替换收益及新Mask是否保留。",'', '完整分析见key_impact_report.md；候选池只有每组8条，离线单边收益不相加，轨迹不同也不能单独归因最终F1。']
  lines+=extra
 (root/'report.md').write_text('\n'.join(lines)+'\n');print(json.dumps(dict(macros=macros,acceptance=acceptance),indent=2))
if __name__=='__main__':main()
